template<class charT, class OutputIterator>
OutputIterator money_put<charT>::put(OutputIterator s, std::ios_base& str, char_type fill, const string_type& digits) const;
// Implementation notes: This member function of std::money_put facet uses virtual dispatch to call std::moneypunct::curr_symbol(), std::moneypunct::decimal_point(), etc., from the imbued locale. The compiler translates this into assembly with indirect calls to vtable entries, e.g., 'call [rax + offset]' for vptr-based dispatch, and handles character mapping via std::ctype. Memory layout involves the locale object pointing to a std::moneypunct instance, which may share memory with other facets in a reference-counted structure.

code_example:
#include <iostream>
#include <locale>
#include <iomanip>

int main() {
    std::locale loc("en_US.UTF-8");  // Sets up a locale with US English formatting
    std::cout.imbue(loc);  // Imbues the stream with the locale, triggering facet lookup
    double amount = 1234.56;
    std::cout << std::showbase << std::put_money(amount) << std::endl;  // Uses money_put facet
    return 0;
}
